package com.honorablemobile

import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34], manifest = Config.NONE, application = android.app.Application::class)
class VideoRollCutReviewTest {
 private val unsafe=JvmTestAllocator
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun rollActivity():HonorableVideoEditorActivity=activity().also{a->val p=VideoEditProject(20000);p.restore(listOf(VideoSegment(0,4000,title="Left",captions=listOf(VideoCaption(3500,4500,"Left cue")),captionSourceUri="content://synthetic/left",motion=VideoMotion(true,endZoom=1.2f,anchorStartMs=0,anchorEndMs=5000)),VideoSegment(6000,10000,speed=2f,title="Right",captions=listOf(VideoCaption(7000,8000,"Right cue")),captionSourceUri="content://synthetic/right"),VideoSegment(12000,15000,title="Later")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(a,"project",p);set(a,"primaryDurationMs",20000L);set(a,"durationMs",20000)}
 private fun pair(a:HonorableVideoEditorActivity):Pair<AlertDialog,AlertDialog>{val editor=dialog();val confirmation=dialog();set(a,"rollCutEditor",editor);set(a,"rollCutConfirmation",confirmation);set(a,"captionReviewDialogs",linkedSetOf(editor,confirmation));return editor to confirmation}
 private fun commit(a:HonorableVideoEditorActivity,pair:Pair<AlertDialog,AlertDialog>,r:VideoCaptionReviewState,delta:Long=500)=call(a,"commitRollCutReview",pair.first,pair.second,r,get(a,"project"),0,delta)as Boolean
 @Test fun exactVisibleRollKeepsPlaybackLengthLaterPositionsSettingsAndOneUndo(){val a=rollActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val music=p.soundtrack;val before=VideoPlaybackTime.durationUs(old);val later=old.take(2).sumOf{it.durationUs};val pair=pair(a);val r=capture(a);assertTrue(commit(a,pair,r));assertEquals(4500L,p.segments[0].endMs);assertEquals(7000L,p.segments[1].startMs);assertEquals(before,VideoPlaybackTime.durationUs(p.segments));assertEquals(later,p.segments.take(2).sumOf{it.durationUs});assertEquals(old[0].copy(endMs=4500),p.segments[0]);assertEquals(old[1].copy(startMs=7000),p.segments[1]);assertSame(old[2],p.segments[2]);assertSame(music,p.soundtrack);assertNull(get(a,"rollCutConfirmation"));assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo);assertTrue(p.redo());assertEquals(4500L,p.segments[0].endMs)}
 @Test fun eitherUntrackedDismissedOrReplacedDialogRejects(){for(which in listOf(0,1))for(flag in listOf("untracked","dismissed","replaced")){val a=rollActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val pair=pair(a);val r=capture(a);when(flag){"untracked"->set(a,"captionReviewDialogs",linkedSetOf(if(which==0)pair.second else pair.first));"dismissed"->showing(if(which==0)pair.first else pair.second,false);else->set(a,if(which==0)"rollCutEditor"else"rollCutConfirmation",dialog())};assertFalse("$which/$flag",commit(a,pair,r));assertSame(old,p.segments);assertFalse(p.canUndo)}}
 @Test fun staleForegroundGenerationSourceDurationRangeMusicSessionAndRecoveryReject(){for(flag in listOf("pause","generation","source","duration","range","music","mode","recovery","busy")){val a=rollActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val pair=pair(a);val r=capture(a);when(flag){"pause"->set(a,"workspaceActive",false);"generation"->set(a,"captionReviewGeneration",r.generation+1);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",20001L);"range"->set(a,"selectedClip",1);"music"->p.setSoundtrack(p.soundtrack!!.copy(volume=.5f));"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"recovery"->set(a,"recoveryBytes",byteArrayOf(1));else->set(a,"saving",true)};assertFalse(flag,commit(a,pair,r));assertSame(old,p.segments);assertNull(get(a,"rollCutConfirmation"))}}
 @Test fun consumedApprovalCannotRepeatOrReviveThroughUndo(){val a=rollActivity();val p=get(a,"project")as VideoEditProject;val pair=pair(a);val r=capture(a);assertTrue(commit(a,pair,r));assertFalse(commit(a,pair,r));assertTrue(p.undo());assertEquals(true,call(a,"canApplyCaptionReview",r));assertFalse(commit(a,pair,r));assertFalse(p.canUndo);assertTrue(p.canRedo)}
 @Test fun foreignOldPairCannotConsumeNewConfirmation(){val a=rollActivity();val old=pair(a);val current=pair(a);val r=capture(a);assertFalse(commit(a,old,r));assertSame(current.second,get(a,"rollCutConfirmation"));assertTrue(commit(a,current,r))}
 @Test fun invalidOffsetConsumesOnlyOwnApprovalWithoutHistory(){for(delta in listOf(0L,1L,2000L)){val a=rollActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val pair=pair(a);val r=capture(a);try{commit(a,pair,r,delta);fail("Accepted $delta")}catch(e:java.lang.reflect.InvocationTargetException){assertTrue(e.cause is IllegalArgumentException)};assertSame(old,p.segments);assertFalse(p.canUndo);assertNull(get(a,"rollCutConfirmation"));assertFalse(commit(a,pair,r,500))}}
 @Test fun approvedRollSurvivesDraftRecoveryWithAnchoredCaptionsMotionAndMusic(){val a=rollActivity();val p=get(a,"project")as VideoEditProject;val pair=pair(a);val r=capture(a);assertTrue(commit(a,pair,r));val first=p.segments[0];val draft=VideoDraft(20000,p.segments,0,0,first.startMs,first.endMs,soundtrack=p.soundtrack);val restored=requireNotNull(VideoDraftCodec.decode(VideoDraftCodec.encode(draft),20000));assertEquals(draft,restored);assertEquals("content://synthetic/left",restored.segments[0].captionSourceUri);assertEquals(3500L,restored.segments[0].captions[0].startMs);assertEquals(5000L,restored.segments[0].motion.anchorEndMs);assertEquals(12000L,restored.segments[2].startMs)}
 @Test fun pausedRollEntryStillReturnsBeforePreviewWidgets(){val a=rollActivity();set(a,"workspaceActive",false);call(a,"rollCut");assertNull(get(a,"rollCutEditor"));assertNull(get(a,"rollCutConfirmation"));assertFalse((get(a,"project")as VideoEditProject).canUndo)}
}
